const j = $input.first().json;

const fromObj = j.from && j.from.value && j.from.value[0] ? j.from.value[0] : null;
const rawFrom = String(j.From || (j.from && j.from.text) || '');
const senderEmail = String((fromObj && fromObj.address) || (rawFrom.match(/<([^>]+)>/) || [])[1] || rawFrom).trim().toLowerCase();
const senderName = String((fromObj && fromObj.name) || rawFrom.replace(/<[^>]*>/, '').replace(/"/g, '').trim() || '').trim();

const subject = String(j.subject || j.Subject || '(no subject)').trim();
let body = String(j.text || j.textPlain || '');
if (!body && j.html) body = String(j.html).replace(/<style[\s\S]*?<\/style>/gi, ' ').replace(/<script[\s\S]*?<\/script>/gi, ' ').replace(/<[^>]+>/g, ' ');
if (!body) body = String(j.snippet || '');
body = body.replace(/\r/g, '').replace(/[ \t]+/g, ' ').replace(/\n{3,}/g, '\n\n').trim().slice(0, 4000);

const headers = j.headers || {};
const autoHeader = String(headers['auto-submitted'] || headers['Auto-Submitted'] || '').toLowerCase();
const isAutomated =
  (autoHeader !== '' && autoHeader !== 'no') ||
  /(^|[._-])(no-?reply|do-?not-?reply|mailer-daemon|postmaster|notifications?|newsletter|bounce)([._-]|@)/i.test(senderEmail) ||
  /(out of office|automatic reply|auto-?reply|undeliverable|delivery status notification)/i.test(subject);

return [{ json: {
  message_id: String(j.id || j.messageId || ''),
  thread_id: String(j.threadId || ''),
  sender_email: senderEmail,
  sender_name: senderName,
  subject,
  body,
  is_automated: isAutomated
} }];

return [{ json: { output: {
  category: 'automated', urgency: 'low', sentiment: 'neutral', confidence: 1,
  summary: 'Automated or no-reply message. No LLM call was made.',
  suggested_reply: '', language: 'en'
} } }];

const mail = $('Normalize Email').first().json;
const raw = $input.first().json || {};

let c = raw.output ?? raw.text ?? raw.response ?? null;
if (typeof c === 'string') { try { c = JSON.parse(c); } catch (e) { c = null; } }
if (c && c.output && typeof c.output === 'object') c = c.output;

const CATEGORIES = ['billing', 'technical_support', 'sales_inquiry', 'complaint', 'feedback', 'account', 'spam', 'automated', 'other'];
const URGENCIES = ['critical', 'high', 'medium', 'low'];
const SENTIMENTS = ['positive', 'neutral', 'negative'];
const SLA_MINUTES = { critical: 60, high: 240, medium: 1440, low: 4320 };

const valid = c && typeof c === 'object' &&
  CATEGORIES.includes(c.category) && URGENCIES.includes(c.urgency) && SENTIMENTS.includes(c.sentiment);
const llmFailed = !valid;

let category = valid ? c.category : 'other';
let urgency = valid ? c.urgency : 'medium';
const sentiment = valid ? c.sentiment : 'neutral';
let confidence = valid ? Number(c.confidence) : 0;
if (!Number.isFinite(confidence)) confidence = 0.5;
confidence = Math.min(1, Math.max(0, confidence));

// Deterministic safety net: the LLM can raise urgency but rules can never lower it.
const text = (mail.subject + ' ' + mail.body).toLowerCase();
const rank = { low: 0, medium: 1, high: 2, critical: 3 };
const bump = level => { if (rank[level] > rank[urgency]) urgency = level; };
if (/(outage|service is down|site is down|production down|data loss|security breach|hacked|cannot log in at all)/.test(text)) bump('critical');
if (/(urgent|asap|immediately|chargeback|legal action|lawyer|refund|cancel my (account|subscription)|double charged)/.test(text)) bump('high');
if (category === 'complaint' && sentiment === 'negative') bump('high');

const isIgnored = category === 'spam' || category === 'automated';
if (isIgnored) urgency = 'low';

const needsReview = !isIgnored && (llmFailed || confidence < 0.6);
const status = isIgnored ? 'ignored' : 'open';
const reply = isIgnored || llmFailed ? '' : String(c.suggested_reply || '').trim().slice(0, 1500);

return [{ json: {
  gmail_message_id: mail.message_id,
  thread_id: mail.thread_id,
  sender_email: mail.sender_email,
  sender_name: mail.sender_name,
  subject: mail.subject,
  body_excerpt: mail.body.slice(0, 1000),
  category, urgency, sentiment, confidence,
  summary: valid ? String(c.summary || '').trim().slice(0, 300) : 'Classification failed. Please review this email manually.',
  suggested_reply: reply,
  language: valid ? String(c.language || 'en').slice(0, 10) : 'en',
  needs_review: needsReview,
  llm_failed: llmFailed,
  status,
  sla_minutes: isIgnored ? '' : String(SLA_MINUTES[urgency]),
  needs_attention: status === 'open' && (urgency === 'critical' || urgency === 'high' || needsReview),
  should_draft: status === 'open' && !llmFailed && reply.length > 0
} }];

const t = $('Validate Classification').first().json;
const saved = $input.first().json;
const due = saved.sla_due_at
  ? new Date(saved.sla_due_at).toLocaleString('en-GB', { timeZone: 'Asia/Jakarta', day: '2-digit', month: 'short', hour: '2-digit', minute: '2-digit' }) + ' WIB'
  : '-';
let msg = (t.urgency === 'critical' ? 'CRITICAL' : t.urgency === 'high' ? 'HIGH PRIORITY' : 'NEEDS REVIEW') + ' - Ticket #' + saved.id + '\n\n';
msg += 'From: ' + (t.sender_name ? t.sender_name + ' <' + t.sender_email + '>' : t.sender_email) + '\n';
msg += 'Subject: ' + t.subject + '\n';
msg += 'Category: ' + t.category + ' | Sentiment: ' + t.sentiment + ' | Confidence: ' + t.confidence.toFixed(2) + '\n';
msg += 'SLA due: ' + due + '\n\n';
msg += t.summary;
if (t.needs_review) msg += '\n\nThe classifier was unsure or failed. Please check this email manually.';
msg += '\n\nReply /resolve ' + saved.id + ' when handled.';
return [{ json: { text: msg } }];

const t = $('Validate Classification').first().json;
const subject = /^re:/i.test(t.subject) ? t.subject : 'Re: ' + t.subject;
return [{ json: { to: t.sender_email, subject, body: t.suggested_reply, thread_id: t.thread_id } }];

const rows = $input.all().map(i => i.json);
const fmt = d => new Date(d).toLocaleString('en-GB', { timeZone: 'Asia/Jakarta', day: '2-digit', month: 'short', hour: '2-digit', minute: '2-digit' });
let msg = 'SLA BREACH - ' + rows.length + ' ticket' + (rows.length > 1 ? 's' : '') + ' escalated

';
msg += rows.map(r => '#' + r.id + ' [' + String(r.urgency).toUpperCase() + '] ' + r.subject + '
   ' + r.sender_email + ' | due ' + fmt(r.sla_due_at)).join('

');
msg += '

Use /open to see all open tickets or /resolve <id> to close one.';
return [{ json: { text: msg } }];

const rows = $input.all().map(i => i.json).filter(r => r && r.id);
const chat_id = $('Normalize Command').first().json.chat_id;
const fmt = d => d ? new Date(d).toLocaleString('en-GB', { timeZone: 'Asia/Jakarta', day: '2-digit', month: 'short', hour: '2-digit', minute: '2-digit' }) : '-';
let t;
if (!rows.length) t = 'No open tickets. Inbox zero!';
else {
  t = 'Open tickets (' + rows.length + (rows.length === 15 ? '+' : '') + ')\n\n';
  t += rows.map(r => '#' + r.id + ' [' + String(r.urgency).toUpperCase() + (r.status === 'escalated' ? ' / ESCALATED' : '') + '] ' + r.subject + '\n   ' + r.category + ' | due ' + fmt(r.sla_due_at)).join('\n\n');
}
return [{ json: { chat_id, reply_text: t } }];

const r = $input.first().json;
const chat_id = $('Normalize Command').first().json.chat_id;
const reply_text = r && r.id
  ? 'Ticket #' + r.id + ' resolved: ' + r.subject
  : 'No open ticket found with that ID. Usage: /resolve <ticket id>';
return [{ json: { chat_id, reply_text } }];

const e = $input.first().json;
const wf = (e.workflow && e.workflow.name) || 'unknown workflow';
const node = (e.execution && e.execution.lastNodeExecuted) || 'unknown node';
const msg = (e.execution && e.execution.error && e.execution.error.message) || 'unknown error';
const url = (e.execution && e.execution.url) || '';
return [{ json: { text: 'WORKFLOW ERROR\n\nWorkflow: ' + wf + '\nFailed node: ' + node + '\nError: ' + String(msg).slice(0, 500) + (url ? '\n' + url : '') } }];
